def search_costs(values, targets):
    result = []
    for target in targets:
        comparisons = 0
        for value in values:
            comparisons += 1
            if value == target:
                break
        result.append(comparisons)
    return result

print(search_costs([], [1, 2]))
print(search_costs([4, 8, 4], [4, 8, 0]))
print(search_costs([4], []))

def observed_cost_range(values, targets):
    if len(targets) == 0:
        return None
    lowest = None
    highest = None
    for target in targets:
        comparisons = 0
        for value in values:
            comparisons += 1
            if value == target:
                break
        if lowest is None or comparisons < lowest:
            lowest = comparisons
        if highest is None or comparisons > highest:
            highest = comparisons
    return lowest, highest

print(observed_cost_range([3, 5, 7], [3, 7, 0]))
print(observed_cost_range([], [2]))
print(observed_cost_range([3], []))
